CREATE OR REPLACE PROCEDURE dbo.sp_ProcessOrder(
    p_CustomerID INT,
    p_ProductID INT,
    p_Quantity INT,
    INOUT p_OrderID INT
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_CurrentStock INT;
    v_Price DECIMAL(10,2);
BEGIN
    -- Check stock
    SELECT StockQuantity INTO v_CurrentStock
    FROM dbo.Products
    WHERE ProductID = p_ProductID;

    IF v_CurrentStock IS NULL THEN
        RAISE EXCEPTION 'Product not found' USING ERRCODE = 'P0001';
    END IF;

    IF v_CurrentStock < p_Quantity THEN
        RAISE EXCEPTION 'Insufficient stock' USING ERRCODE = 'P0001';
    END IF;

    -- Get price
    SELECT Price INTO v_Price
    FROM dbo.Products
    WHERE ProductID = p_ProductID;

    -- Create order
    INSERT INTO dbo.Orders (CustomerID, TotalAmount, Status)
    VALUES (p_CustomerID, v_Price * p_Quantity, 'Processing')
    RETURNING OrderID INTO p_OrderID;

    -- Create order item
    INSERT INTO dbo.OrderItems (OrderID, ProductID, Quantity, UnitPrice)
    VALUES (p_OrderID, p_ProductID, p_Quantity, v_Price);

    -- Update stock
    UPDATE dbo.Products
    SET StockQuantity = StockQuantity - p_Quantity
    WHERE ProductID = p_ProductID;

    -- Transaction is automatically committed if no exception occurs
EXCEPTION
    WHEN OTHERS THEN
        -- Transaction is automatically rolled back on exception
        RAISE;
END;
$$;
